-- Solo lectura: consultas usadas para documentar el esquema; no ejecutar DDL.
select jsonb_build_object(
'capturado', current_timestamp,
'esquemas',(select jsonb_agg(jsonb_build_object('nombre',nspname,'comentario',obj_description(oid,'pg_namespace'))) from pg_namespace where nspname in ('public','nfc_m28_privado')),
'extensiones',(select jsonb_agg(jsonb_build_object('nombre',e.extname,'version',e.extversion,'esquema',n.nspname)) from pg_extension e join pg_namespace n on n.oid=e.extnamespace),
'tablas',(select jsonb_agg(jsonb_build_object('esquema',n.nspname,'nombre',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'comentario',obj_description(c.oid,'pg_class'),
'columnas',(select jsonb_agg(jsonb_build_object('nombre',a.attname,'tipo',format_type(a.atttypid,a.atttypmod),'nulo',not a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'comentario',col_description(c.oid,a.attnum)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
'constraints',(select jsonb_agg(jsonb_build_object('nombre',conname,'tipo',contype,'definicion',pg_get_constraintdef(oid,true),'comentario',obj_description(oid,'pg_constraint'))) from pg_constraint where conrelid=c.oid),
'indices',(select jsonb_agg(jsonb_build_object('nombre',ci.relname,'definicion',pg_get_indexdef(i.indexrelid),'constraint',exists(select 1 from pg_constraint co where co.conindid=i.indexrelid),'comentario',obj_description(ci.oid,'pg_class'))) from pg_index i join pg_class ci on ci.oid=i.indexrelid where i.indrelid=c.oid),
'triggers',(select jsonb_agg(jsonb_build_object('nombre',t.tgname,'definicion',pg_get_triggerdef(t.oid,true),'habilitado',t.tgenabled,'comentario',obj_description(t.oid,'pg_trigger'))) from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal)
)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','nfc_m28_privado') and c.relkind in ('r','p')),
'politicas',(select jsonb_agg(to_jsonb(p)) from pg_policies p where schemaname in ('public','nfc_m28_privado')),
'funciones',(select jsonb_agg(jsonb_build_object('esquema',n.nspname,'nombre',p.proname,'firma',pg_get_function_identity_arguments(p.oid),'definicion',pg_get_functiondef(p.oid),'comentario',obj_description(p.oid,'pg_proc'))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','nfc_m28_privado') and p.prokind in ('f','p') and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
'secuencias',(select jsonb_agg(jsonb_build_object('esquema',n.nspname,'nombre',c.relname,'tipo',format_type(s.seqtypid,null),'inicio',s.seqstart,'incremento',s.seqincrement,'minimo',s.seqmin,'maximo',s.seqmax,'cache',s.seqcache,'ciclo',s.seqcycle,'identity',exists(select 1 from pg_depend d where d.classid='pg_class'::regclass and d.objid=c.oid and d.deptype='i'),'tabla',tn.nspname||'.'||tc.relname,'columna',a.attname)) from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace left join pg_depend dep on dep.classid='pg_class'::regclass and dep.objid=c.oid and dep.deptype in ('a','i') left join pg_class tc on tc.oid=dep.refobjid left join pg_namespace tn on tn.oid=tc.relnamespace left join pg_attribute a on a.attrelid=tc.oid and a.attnum=dep.refobjsubid where n.nspname in ('public','nfc_m28_privado'))
) as catalogo;

select jsonb_build_object(
'tipos',(select jsonb_agg(jsonb_build_object('esquema',n.nspname,'nombre',t.typname,'tipo',t.typtype,'etiquetas',(select jsonb_agg(e.enumlabel order by e.enumsortorder) from pg_enum e where e.enumtypid=t.oid))) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in ('public','nfc_m28_privado') and t.typtype in ('e','d') and not exists(select 1 from pg_depend d where d.classid='pg_type'::regclass and d.objid=t.oid and d.deptype='e')),
'vistas',(select jsonb_agg(jsonb_build_object('esquema',n.nspname,'nombre',c.relname,'definicion',pg_get_viewdef(c.oid,true),'tipo',c.relkind,'opciones',c.reloptions)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','nfc_m28_privado') and c.relkind in ('v','m')),
'acl_relaciones',(select jsonb_agg(jsonb_build_object('esquema',n.nspname,'nombre',c.relname,'acl',c.relacl,'propietario',pg_get_userbyid(c.relowner))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','nfc_m28_privado') and c.relkind in ('r','p','S')),
'acl_funciones',(select jsonb_agg(jsonb_build_object('esquema',n.nspname,'nombre',p.proname,'firma',pg_get_function_identity_arguments(p.oid),'acl',p.proacl,'propietario',pg_get_userbyid(p.proowner))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','nfc_m28_privado') and p.prokind in ('f','p') and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
'acl_esquemas',(select jsonb_agg(jsonb_build_object('nombre',nspname,'acl',nspacl,'propietario',pg_get_userbyid(nspowner))) from pg_namespace where nspname in ('public','nfc_m28_privado')),
'privilegios_por_defecto',(select jsonb_agg(jsonb_build_object('rol',pg_get_userbyid(d.defaclrole),'esquema',n.nspname,'tipo',d.defaclobjtype,'acl',d.defaclacl)) from pg_default_acl d join pg_namespace n on n.oid=d.defaclnamespace where n.nspname in ('public','nfc_m28_privado'))
) as extras;

-- Única lectura de metadatos de programación solicitada fuera de pg_catalog:
select jobid, schedule, command, database, active, jobname from cron.job order by jobid;
